+    @ConvertEvaluator(extraName = "FromWKB", warnExceptions = { IllegalArgumentException.class })
+    static BytesRef fromWellKnownBinary(BytesRef wkb) {
+        var geometry = UNSPECIFIED.wkbToGeometry(wkb);
